"""Caller-owned operator-exact S/SDG rules for a CX/U3 target."""

import math
from collections.abc import Mapping
from dataclasses import replace

from flagquantum.compiler.basis_translation import (
    EquivalenceRule,
    with_equivalence_rule,
)
from flagquantum.core.ir import CircuitIR, Instruction

from ...classiq_qsvt.overview.exact_basis import exact_rules as qsvt_rules
from ...classiq_qsvt.overview.exact_basis import rz_to_two_u3


def s_to_u3(instruction: Instruction) -> tuple[Instruction, ...]:
    """Preserve diag(1,i) exactly, including absolute phase."""
    return (
        Instruction(
            "u3",
            instruction.wires,
            params={"theta": 0.0, "phi": 0.0, "lbd": math.pi / 2},
            metadata=instruction.metadata,
        ),
    )


def sdg_to_u3(instruction: Instruction) -> tuple[Instruction, ...]:
    """Preserve diag(1,-i) exactly, including absolute phase."""
    return (
        Instruction(
            "u3",
            instruction.wires,
            params={"theta": 0.0, "phi": 0.0, "lbd": -math.pi / 2},
            metadata=instruction.metadata,
        ),
    )


def rx_to_u3(instruction: Instruction) -> tuple[Instruction, ...]:
    """RX(theta) equals U3(theta,-pi/2,pi/2), without a quarter-turn scalar."""
    return (
        Instruction(
            "u3",
            instruction.wires,
            params={
                "theta": instruction.params["theta"],
                "phi": -math.pi / 2,
                "lbd": math.pi / 2,
            },
            metadata=instruction.metadata,
        ),
    )


def exact_rules() -> Mapping[str, tuple[EquivalenceRule, ...]]:
    """Add local exact identities; leave shared decomposition tables untouched."""
    rules = with_equivalence_rule(qsvt_rules(), "s", s_to_u3)
    rules = with_equivalence_rule(rules, "sdg", sdg_to_u3)
    return with_equivalence_rule(rules, "rx", rx_to_u3)


def preserve_rotation_phases(program: CircuitIR) -> CircuitIR:
    """Expand source RX/RZ before generic quarter-turn simplification.

    Generic quarter-turn words may retain an operator only up to scalar phase.
    This caller compares absolute amplitudes, so exact U3 identities are required
    even for pi/2, pi and zero angles. No shared compiler table is changed.
    """
    return replace(
        program,
        instructions=tuple(
            leaf
            for instruction in program.instructions
            for leaf in (
                rx_to_u3(instruction)
                if instruction.name == "rx"
                else (
                    rz_to_two_u3(instruction)
                    if instruction.name == "rz"
                    else (instruction,)
                )
            )
        ),
    )

"""Operator-exact caller-owned RZ identity for the source CX/U3 target."""

import math
from collections.abc import Mapping

from examples.synthesis.tutorials.technology_demonstrations.classiq_paper.quantum_walk.classiq_discrete_quantum_walk.overview.exact_basis import (
    exact_rules as walk_rules,
)
from flagquantum.compiler.basis_translation import (
    EquivalenceRule,
    with_equivalence_rule,
)
from flagquantum.core.ir import Instruction


def rz_to_two_u3(instruction: Instruction) -> tuple[Instruction, ...]:
    # In execution order U3(pi,0,pi-t/2) @ U3(pi,0,pi+t/2) = RZ(t).
    half = instruction.params["theta"] * 0.5
    return tuple(
        Instruction(
            "u3",
            instruction.wires,
            params={"theta": math.pi, "phi": 0.0, "lbd": math.pi + angle},
            metadata=instruction.metadata,
        )
        for angle in (half, -half)
    )


def exact_rules() -> Mapping[str, tuple[EquivalenceRule, ...]]:
    return with_equivalence_rule(walk_rules(), "rz", rz_to_two_u3)

"""Operator-exact rules for a caller-requested CX/U3 named basis."""

import math
from collections.abc import Mapping

from flagquantum.compiler.basis_translation import (
    EQUIVALENCE_RULES,
    EquivalenceRule,
    with_equivalence_rule,
)
from flagquantum.core.ir import Instruction


def h_to_u3(instruction: Instruction) -> tuple[Instruction, ...]:
    """H equals U3(pi/2,0,pi), including its absolute phase."""
    return (
        Instruction(
            "u3",
            instruction.wires,
            params={"theta": math.pi / 2, "phi": 0.0, "lbd": math.pi},
            metadata=instruction.metadata,
        ),
    )


def phase_to_u3(instruction: Instruction) -> tuple[Instruction, ...]:
    """A phase gate equals U3(0,0,theta)."""
    return (
        Instruction(
            "u3",
            instruction.wires,
            params={"theta": 0.0, "phi": 0.0, "lbd": instruction.params["theta"]},
            metadata=instruction.metadata,
        ),
    )


def cphase_to_u3_cx(instruction: Instruction) -> tuple[Instruction, ...]:
    """Use three phase gates and two CX gates without a lost global phase."""
    control, target = instruction.wires
    half = instruction.params["theta"] * 0.5
    metadata = instruction.metadata
    return (
        Instruction(
            "u3",
            (control,),
            params={"theta": 0.0, "phi": 0.0, "lbd": half},
            metadata=metadata,
        ),
        Instruction(
            "u3",
            (target,),
            params={"theta": 0.0, "phi": 0.0, "lbd": half},
            metadata=metadata,
        ),
        Instruction("cx", (control, target), metadata=metadata),
        Instruction(
            "u3",
            (target,),
            params={"theta": 0.0, "phi": 0.0, "lbd": -half},
            metadata=metadata,
        ),
        Instruction("cx", (control, target), metadata=metadata),
    )


def x_to_u3(instruction: Instruction) -> tuple[Instruction, ...]:
    return (
        Instruction(
            "u3",
            instruction.wires,
            params={"theta": math.pi, "phi": 0.0, "lbd": math.pi},
            metadata=instruction.metadata,
        ),
    )


def t_to_u3(instruction: Instruction) -> tuple[Instruction, ...]:
    return (
        Instruction(
            "u3",
            instruction.wires,
            params={"theta": 0.0, "phi": 0.0, "lbd": math.pi / 4},
            metadata=instruction.metadata,
        ),
    )


def tdg_to_u3(instruction: Instruction) -> tuple[Instruction, ...]:
    return (
        Instruction(
            "u3",
            instruction.wires,
            params={"theta": 0.0, "phi": 0.0, "lbd": -math.pi / 4},
            metadata=instruction.metadata,
        ),
    )


def exact_rules() -> Mapping[str, tuple[EquivalenceRule, ...]]:
    """Extend the immutable public rule table; leave all shared defaults untouched."""
    rules = EQUIVALENCE_RULES
    for opcode, builder in (
        ("h", h_to_u3),
        ("phase", phase_to_u3),
        ("cphase", cphase_to_u3_cx),
        ("x", x_to_u3),
        ("t", t_to_u3),
        ("tdg", tdg_to_u3),
    ):
        rules = with_equivalence_rule(rules, opcode, builder)
    return rules
